let listaMaestra = [...dbsArg, ...dbsCines, ...dbsCol, ...dbsCol4];

let inputVigia = [];
try {
  inputVigia = $("When Executed by Another Workflow").all();
} catch (e) {}

if (inputVigia.length > 0) {
  const control = inputVigia[0].json;

  // ESCENARIO A: Recuperación Parcial (El Vigía mandó una lista de entornos)
  if (control.Pais && control.Entorno) {
