        v.json.Entorno === m.json.entorno
      );
    });
  } 

  // ESCENARIO B: Recuperación Total (EJECUTAR_PRINCIPAL)
  // No filtramos nada, se devuelven los 17 entornos.
  else if (control.escenario === "EJECUTAR_PRINCIPAL") {
    // Simplemente dejamos la listaMaestra intacta.
  }
}

return listaMaestra;

const audit = $('Update Metrics').item.json;
const ctx   = $('Query Loop').first().json;
const out   = JSON.parse(JSON.stringify(ctx));

let rows = [], estado;
if (audit.status === false) {
  estado = 'ERROR';
} else {
  rows = $('SQL Execute').all().map(i => i.json).filter(j => Object.keys(j).length > 0);
  estado = rows.length ? 'OK' : 'VACIO';
}

out.result        = rows;
out._status       = estado;          // OK | VACIO | ERROR
out._isError      = audit.status === false;
out._errorMessage = audit.error_message || null;
out.filas         = audit.filas_encontradas;
return { json: out };

// [NODO: Set HTML - modo per-item]
// Corre 1 vez por resultado (item) que llega desde Tag First Message.
// Devuelve como mucho 1 mensaje por item: si el item no tiene
// datos, no seteamos htmlContent y el If1 lo saltea sin enviar nada.
// El item marcado con _isFirstMessage (por 'Tag First Message') lleva
// además el encabezado de fecha/frecuencia/aplicación, una sola vez
// por corrida de este entorno.

const item = $input.item.json;
const APP_NAME = "COMFIAR";

const styles = {
  container: "font-family:sans-serif;font-size:13px;color:#000;",
  h3: "font-size:15px;font-weight:bold;margin:0 0 8px 0;",
  errorTitle: "font-size:15px;font-weight:bold;margin:0 0 8px 0;color:#d9534f;",
  table: "width:100%;border-collapse:collapse;",
  pre: "font-family:monospace;font-size:11px;background:#f4f4f4;padding:8px;border:1px solid #ccc;",
  notice: "font-size:11px;font-style:italic;",
};

let reportType = "General";
try {
  reportType = $("Credentials Loop").first().json["type"] || "General";
} catch (e) {}

let frequency = "General";
if (reportType === "Daily") frequency = "Diaria";
else if (reportType === "Four-hourly") frequency = "cada 4 horas";
else if (reportType === "Hourly") frequency = "cada 1 hora";
else if (reportType === "Bi-hourly") frequency = "cada 2 horas";
else if (reportType === "Monthly") frequency = "Mensual";

// La etiqueta "Revisión {frecuencia} — COMFIAR" va SIEMPRE, en los N mensajes,
// para poder identificar a qué corrida corresponde cada notificación (pueden
// mezclarse con las de otro trigger en el mismo canal). La fecha (solo Daily)
// va únicamente en el primer mensaje de cada entorno (_isFirstMessage).
let headerHtml = `<div style="${styles.container}">`;
if (item._isFirstMessage && reportType === "Daily") {
  const now = new Date();
  const dateStr = now.toLocaleDateString("es-ES", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const dateFormatted = dateStr.charAt(0).toUpperCase() + dateStr.slice(1);
  headerHtml += `<h1 style="font-size:20px;margin:0;">${dateFormatted}</h1>`;
}
headerHtml += `<h2 style="font-size:13px;margin:0 0 15px 0;text-transform:uppercase;font-weight:normal;">Revisión ${frequency} — ${APP_NAME}</h2>`;
headerHtml += `</div>`;

// CASO ERROR: la query de este item falló en la ejecución.
if (item._isError === true) {
  const desc = item.description || "Sin descripción";
  const errMsg = (item._errorMessage || "Error desconocido")
    .toString()
    .slice(0, 300);
  const html = `<div style="${styles.container}"><h3 style="${styles.errorTitle}">⚠️ Punto ${item.queryId}: ${desc}</h3><p>${errMsg}</p></div>`;
  return { json: { htmlContent: headerHtml + html, queryId: item.queryId } };
}

// Validar si el resultado está vacío -> no se envía mensaje para este item.
const results = item.result;
let isEmpty = false;
if (!results || (Array.isArray(results) && results.length === 0)) {
  isEmpty = true;
} else if (Array.isArray(results) && results.length === 1) {
  const firstItem = results[0];
  if (
    firstItem === null ||
    (typeof firstItem === "object" && Object.keys(firstItem).length === 0)
  ) {
    isEmpty = true;
  }
}

if (isEmpty) {
  return { json: { queryId: item.queryId } };
}

const MAX_ROWS = 150;
const MAX_COLS = 10;
let data = results.length > MAX_ROWS ? results.slice(0, MAX_ROWS) : results;
let fullHeaders = Object.keys(data[0] || {});
let headers =
  fullHeaders.length > MAX_COLS ? fullHeaders.slice(0, MAX_COLS) : fullHeaders;

let html = `<div style="${styles.container}"><h3 style="${styles.h3}">Punto ${item.queryId}: ${item.description || "Sin descripción"}</h3>`;

html += `<table border="1" cellpadding="4" cellspacing="0" style="${styles.table}"><thead><tr bgcolor="#f2f2f2">`;
for (const h of headers) html += `<th align="left">${h}</th>`;
html += "</tr></thead><tbody>";

for (const row of data) {
  html += "<tr>";
  for (const h of headers) {
    const val = row[h];
    const cleanVal =
      val === null || val === undefined
        ? ""
        : String(val).replace(/</g, "&lt;").replace(/>/g, "&gt;");
    html += `<td>${cleanVal}</td>`;
  }
  html += "</tr>";
}
html += "</tbody></table>";

if (results.length > MAX_ROWS || fullHeaders.length > MAX_COLS) {
  html += `<p style="${styles.notice}">(Vista limitada: ${results.length > MAX_ROWS ? MAX_ROWS + " filas " : ""}${fullHeaders.length > MAX_COLS ? MAX_COLS + " columnas" : ""})</p>`;
}

if (String(item.pattern || "0").trim() === "2") {
  const combinedQueryText = `-- SELECT\n${item.revisionQuery || ""}\n\n-- UPDATE\n${item.correctionQuery || ""}`;
  html += `<p><b>Cargar ticket con:</b></p><pre style="${styles.pre}">${combinedQueryText}</pre>`;
}

html += `</div>`;

return { json: { htmlContent: headerHtml + html, queryId: item.queryId } };

// [NODO: FAN IN - AGREGADOR]
// MODO: Run Once for All Items

const groupedItems = new Map();
const finalOutput = [];

const hasData = (sqlResultData) => {
  if (!sqlResultData || !Array.isArray(sqlResultData) || sqlResultData.length === 0) return false;
  return sqlResultData.some(row => (row && Object.keys(row).length > 0));
};

for (const item of items) {
  const json = item.json;
  const parentId = json.parentGroupId;

  // --- CASO 1: ITEM NORMAL ---
  if (!parentId) {
    finalOutput.push(item);
    continue;
  }

  // --- CASO 2: ITEM PARTICIONADO ---
  if (hasData(json.result)) {
    if (!groupedItems.has(parentId)) {
      const baseItem = JSON.parse(JSON.stringify(item));
      if (baseItem.json.associatedCorrection) {
         baseItem.json.correctionQuery = baseItem.json.associatedCorrection;
      }
      baseItem.json.revisionQuery = (baseItem.json.revisionQuery || '').trim();
      baseItem.json.correctionQuery = (baseItem.json.correctionQuery || '').trim();
      groupedItems.set(parentId, baseItem);
    } else {
      const groupItem = groupedItems.get(parentId);
      const currentJson = json;
      groupItem.json.result.push(...currentJson.result);

      if (currentJson.revisionQuery) {
        groupItem.json.revisionQuery += '\n\n' + currentJson.revisionQuery.trim();
      }
      const currentCorrection = currentJson.associatedCorrection || currentJson.correctionQuery;
      if (currentCorrection) {
        const prevCorrection = groupItem.json.correctionQuery;
        groupItem.json.correctionQuery = prevCorrection 
          ? prevCorrection + '\n\n' + currentCorrection.trim() 
          : currentCorrection.trim();
      }
    }
  }
}

// Volcamos los grupos al array final
for (const groupItem of groupedItems.values()) {
  const json = groupItem.json;
  delete json.parentGroupId;
  delete json.subQueryIndex;
  delete json.queryType;
  delete json.associatedCorrection;
  groupItem.json = json;
  finalOutput.push(groupItem);
}

// CORRECCIÓN DE ORDEN: Ordenamos por queryId (ej: 1.2, 1.3, 1.4)
// Asumimos que queryId es un string como "1.2", "1.3", "4.9". 
// Usamos localeCompare con 'numeric: true' para que ordene bien números (2 vs 10).
finalOutput.sort((a, b) => {
    const idA = String(a.json.queryId || '');
    const idB = String(b.json.queryId || '');
    return idA.localeCompare(idB, undefined, { numeric: true, sensitivity: 'base' });
});

return finalOutput;

const items = $input.all();
const credentials = $node["Credentials Loop"].json
for (const item of items) {
  // 1. Obtenemos el timezone que definimos en las credenciales
  const zone = $node["Credentials Loop"].json.timezone; 

  // 2. Calculamos la hora fresca
  // Importante: DateTime es global en n8n
  item.json.hora_ejecucion_real = DateTime.now()
    .setZone(zone)
    .toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS");

  // Timestamp para auditoría (milisegundos)
  item.json.audit_startTime = new Date().getTime();
  item.json.timeout = 90000,
  item.json.user=credentials.user,
  item.json.password=credentials.password,
  item.json.database=credentials.database,
  item.json.port=credentials.port,
  item.json.server= credentials.server_host
  item.json.flag = "comfiar"
}

return items;

const results = $input.all();
const errorMsg = typeof results[0]?.json?.error === 'string' ? results[0].json.error : null;
const hasError = !!errorMsg;

// Unificamos el objeto de fecha
const now = new Date();
const start = $('Audit Start').item?.json?.audit_startTime || $('Audit Start').first().json.audit_startTime;

const e = $('Credentials Loop').item?.json || {};
const q = $('Query Loop').item?.json || {};

// Asumimos que estas variables se calculan aquí en base a los resultados si no hay error
const realResultsCount = hasError ? 0 : results.length;
const sizeInBytes = hasError ? 0 : JSON.stringify(results).length; // Ejemplo de cálculo si no venía definido

return [{
  json: {
    query:             q.queryId     || 'N/A',
    pais:              e.country     || 'Desconocido',
    entorno:           e.entorno     || 'Desconocido',
    frecuencia:        q.type        || 'N/A',
    description:       q.description || 'Sin descripción',
    aplicacion:        q.application || 'N/A',
    tiempo:            +((now - start) / 1000).toFixed(2), // '+' reemplaza a parseFloat
    peso:              +((sizeInBytes / 1024).toFixed(2)),
    filas_encontradas: realResultsCount,
    timestamp_tz:      now.toISOString().split('.')[0].replace('T', ' ') + '+00',
    fecha_real:        now.toLocaleDateString("en-CA", { timeZone: "America/Argentina/Buenos_Aires" }),
    hora_limpia:       now.toLocaleTimeString("en-GB", { timeZone: "America/Argentina/Buenos_Aires" }),
    status:            !hasError,
    error_message:     errorMsg || null
  }
}];

// [NODO: Tag First Message]
// Corre 1 vez para todos los items (post Fan In). Marca cuál va a ser
// el PRIMER mensaje que realmente se envía a Teams en esta corrida del
// entorno (el primero con error o con datos, en el mismo orden en que
// Fan In los dejó). Set  HTML usa esa marca para pegarle el encabezado
// de fecha/frecuencia/aplicación una sola vez, no en cada mensaje.

const hasContent = (json) => {
  if (json._isError === true) return true;
  const results = json.result;
  if (!results || (Array.isArray(results) && results.length === 0)) return false;
  if (Array.isArray(results) && results.length === 1) {
    const first = results[0];
    if (first === null || (typeof first === 'object' && Object.keys(first).length === 0)) return false;
  }
  return true;
};

let tagged = false;
for (const entry of items) {
  if (!tagged && hasContent(entry.json)) {
    entry.json._isFirstMessage = true;
    tagged = true;
  }
}

return items;

const teamsResponse = $input.first().json;
const cred = $('Credentials Loop').first().json;
const msgItem = $('Message Loop').first().json;

return {
  json: {
    message_id: teamsResponse.id || null,
    query_id: msgItem.queryId,
    pais: cred.country,
    entorno: cred.entorno,
    channel_name: `${cred.country} ${cred.entorno}`,
    channel_id: cred.channelId,
    status: true
  }
};
